HERE=pathlib.Path(__file__).parent

def fingerprint(record):return {k:record.get(k) for k in ['id','heading','heading_source','toc_heading','path','parent_id','canonical_body_key','body_sha256','raw_sha256','source_url','kind','text','assets','image_refs']}
def normalize(value):return ''.join(c.casefold() for c in value if c.isalnum())
def qualify(records,config):
 if hash_json(config)!=CONFIG_SHA:return records
 for ident,q in QUALIFICATIONS.items():
  record=records.get(ident)
  if not record or fingerprint(record)!=q['record']:continue
  parent=None
  if q.get('required_parent'):
   parent=records.get(q['required_parent']['fingerprint']['id'])
   if not parent or fingerprint(parent)!=q['required_parent']['fingerprint'] or digest(parent['text'].encode())!=q['required_parent']['text_sha256']:continue
  try:
   for item in q['fixture_witnesses']:
    p=HERE/item['path']
    if not p.is_file() or digest(p.read_bytes())!=item['sha256']:raise ValueError('Changed retained source/native witness')
   data=(HERE/q['selected_native_path']).read_bytes()
   if digest(data)!=q['selected_native_sha256']:continue
   from pypdf import PdfReader
   reader=PdfReader(io.BytesIO(data),strict=True)
   if len(reader.pages)!=q['selected_native_pages']:continue
   text='\n'.join(p.extract_text() or '' for p in reader.pages)
   if digest(normalize(text).encode())!=q['selected_native_text_sha256']:continue
   if parent and not all(normalize(line) in normalize(text) for line in parent['text'].splitlines() if line.strip()):continue
   remaining=normalize(re.sub(r'Page\s+\d+','',text,flags=re.I))
   allowed=q['allowed_observed_heading_path']+(parent['text'].splitlines() if parent else [])
   for part in sorted(allowed,key=lambda part:len(normalize(part)),reverse=True):
    if part.strip():remaining=remaining.replace(normalize(part),'')
   if remaining:continue
  except Exception:continue
  record['kind']='confirmed_source_empty'
  record['disposition']='Exact retained HTML/native witness confirms source-empty owned node. Actual source hierarchy/ID retained; no invented legal text, repeal, structural exclusion or duplicate descendant body.'
  record['source_empty_qualification']={'type':q['source_surface_disposition'],'source_native_binding':copy.deepcopy(q),'scope':'Faithful collection of this exact source-empty node only; not a legal assertion that no operative rule exists outside retained source.'}
 return records
